# Node Version Manager, as nvmimic provides it.
#
# This file defines the same shell functions nvm's nvm.sh defines. Small ones
# are copied from nvm unchanged. The rest, `nvm` included, hand their work to
# the nvmimic binary in $NVM_DIR/.nvmimic/bin, so sourcing this file starts no
# other program.
#
# This file is generated by `cargo xtask gen-shell`. Edit the generator.
#
# Parts of this file are copied from nvm (https://github.com/nvm-sh/nvm),
# MIT licensed: Copyright (c) 2010 Tim Caswell, Copyright (c) 2014 Jordan Harband.
# nvmimic is MIT licensed: Copyright (c) 2026 Taylor Silenzio.

# shellcheck disable=SC2039,SC2016,SC2001,SC3043
{ # this ensures the entire script is downloaded #

# shellcheck disable=SC3028
NVM_SCRIPT_SOURCE="${_:-}"
nvm_is_zsh() {
  [ -n "${ZSH_VERSION-}" ]
}

nvm_stdout_is_terminal() {
  [ -t 1 ]
}

nvm_echo() {
  command printf %s\\n "$*" 2>/dev/null
}

nvm_echo_with_colors() {
  command printf %b\\n "$*" 2>/dev/null
}

nvm_cd() {
  \cd "$@"
}

nvm_err() {
  (>&2 nvm_echo "$@") || return 0
}

nvm_err_with_colors() {
  (>&2 nvm_echo_with_colors "$@") || return 0
}

nvm_grep() {
  GREP_OPTIONS='' command grep "$@"
}

nvm_has() {
  type "${1-}" >/dev/null 2>&1
}

nvm_has_executable() {
  (
    # `|| true` so that shells with errexit-style options (eg, zsh's ERR_RETURN)
    # do not abort the subshell when the name is not an alias or a function
    unalias "${1-}" 2>/dev/null || true
    unset -f "${1-}" 2>/dev/null || true
    command -v "${1-}" >/dev/null 2>&1
  )
}

nvm_has_non_aliased() {
  nvm_has "${1-}" && ! nvm_is_alias "${1-}"
}

nvm_is_alias() {
  # this is intentionally not "command alias" so it works in zsh.
  \alias "${1-}" >/dev/null 2>&1
}

nvm_command_info() {
  local COMMAND
  local INFO
  COMMAND="${1}"
  if type "${COMMAND}" | nvm_grep -q hashed; then
    INFO="$(type "${COMMAND}" | command sed -E 's/\(|\)//g' | command awk '{print $4}')"
  elif type "${COMMAND}" | nvm_grep -q aliased; then
    # shellcheck disable=SC2230
    INFO="$(which "${COMMAND}") ($(type "${COMMAND}" | command awk '{ $1=$2=$3=$4="" ;print }' | command sed -e 's/^\ *//g' -Ee "s/\`|'//g"))"
  elif type "${COMMAND}" | nvm_grep -q "^${COMMAND} is an alias for"; then
    # shellcheck disable=SC2230
    INFO="$(which "${COMMAND}") ($(type "${COMMAND}" | command awk '{ $1=$2=$3=$4=$5="" ;print }' | command sed 's/^\ *//g'))"
  elif type "${COMMAND}" | nvm_grep -q "^${COMMAND} is /"; then
    INFO="$(type "${COMMAND}" | command awk '{print $3}')"
  else
    INFO="$(type "${COMMAND}")"
  fi
  nvm_echo "${INFO}"
}

nvm_tree_contains_path() {
  local tree
  tree="${1-}"
  local node_path
  node_path="${2-}"

  if [ "@${tree}@" = "@@" ] || [ "@${node_path}@" = "@@" ]; then
    nvm_err "both the tree and the node path are required"
    return 2
  fi

  local clean_tree
  clean_tree="${tree}"

  # Strip trailing slashes in shell memory (e.g., "dir//" -> "dir")
  while [ "${clean_tree}" != "${clean_tree%/}" ]; do
    clean_tree="${clean_tree%/}"
  done
  if [ -z "${clean_tree}" ]; then
    clean_tree='/'
  fi

  # Pure in-memory POSIX parent-walk using parameter expansion instead of subshell dirname forks.
  # Uses literal string equality [ "${pathdir}" = "${clean_tree}" ] to prevent glob expansion bugs.
  local pathdir
  pathdir="${node_path}"
  while [ "${pathdir}" != '' ] && [ "${pathdir}" != '.' ] && [ "${pathdir}" != '/' ] &&
      [ "${pathdir}" != "${clean_tree}" ]; do
    case "${pathdir}" in
      */*)
        pathdir="${pathdir%/*}"
        if [ -z "${pathdir}" ]; then
          pathdir='/'
        fi
        ;;
      *)
        break
        ;;
    esac
  done
  [ "${pathdir}" = "${clean_tree}" ]
}

nvm_find_project_dir() {
  local path_
  path_="${PWD}"
  while [ "${path_}" != "" ] && [ "${path_}" != '.' ] && [ ! -f "${path_}/package.json" ] && [ ! -d "${path_}/node_modules" ]; do
    path_=${path_%/*}
  done
  nvm_echo "${path_}"
}

nvm_find_up() {
  local path_
  path_="${PWD}"
  while [ "${path_}" != "" ] && [ "${path_}" != '.' ] && [ ! -f "${path_}/${1-}" ]; do
    path_=${path_%/*}
  done
  nvm_echo "${path_}"
}

nvm_find_nvmrc() {
  local dir
  dir="$(nvm_find_up '.nvmrc')"
  if [ -e "${dir}/.nvmrc" ]; then
    nvm_echo "${dir}/.nvmrc"
  fi
}

nvm_version_dir() {
  local NVM_WHICH_DIR
  NVM_WHICH_DIR="${1-}"
  if [ -z "${NVM_WHICH_DIR}" ] || [ "${NVM_WHICH_DIR}" = "new" ]; then
    nvm_echo "${NVM_DIR}/versions/node"
  elif [ "_${NVM_WHICH_DIR}" = "_iojs" ]; then
    nvm_echo "${NVM_DIR}/versions/io.js"
  elif [ "_${NVM_WHICH_DIR}" = "_old" ]; then
    nvm_echo "${NVM_DIR}"
  else
    nvm_err 'unknown version dir'
    return 3
  fi
}

nvm_alias_path() {
  nvm_echo "$(nvm_version_dir old)/alias"
}

nvm_hash_reset() {
  # under `set +h` there is no cache to clear, and `hash -r` errors
  if [ -n "${BASH_VERSION-}" ] && [ "${-#*h}" = "$-" ]; then
    return 0
  fi
  # `ksh93`'s `hash` takes no `-r` and its usage error is fatal; probing in a
  # subshell contains it, and spares the `ksh` variants that do accept `-r`
  if [ -n "${KSH_VERSION-}" ] && ! ( \hash -r ) >/dev/null 2>&1; then
    return 0
  fi
  \hash -r
}

nvm_iojs_prefix() {
  nvm_echo 'iojs'
}

nvm_node_prefix() {
  nvm_echo 'node'
}

nvm_is_iojs_version() {
  case "${1-}" in iojs-*) return 0 ;; esac
  return 1
}

nvm_strip_iojs_prefix() {
  local NVM_IOJS_PREFIX
  NVM_IOJS_PREFIX="$(nvm_iojs_prefix)"

  case "${1-}" in
    "${NVM_IOJS_PREFIX}") nvm_echo ;;
    *) nvm_echo "${1#"${NVM_IOJS_PREFIX}"-}" ;;
  esac
}

nvm_cache_dir() {
  nvm_echo "${NVM_DIR}/.cache"
}

nvm_is_natural_num() {
  if [ -z "$1" ]; then
    return 4
  fi
  case "$1" in
    0) return 1 ;;
    -*) return 3 ;; # some BSDs return false positives for double-negated args
    *)
      [ "$1" -eq "$1" ] 2>/dev/null # returns 2 if it doesn't match
    ;;
  esac
}

nvm_validate_implicit_alias() {
  local NVM_IOJS_PREFIX
  NVM_IOJS_PREFIX="$(nvm_iojs_prefix)"
  local NVM_NODE_PREFIX
  NVM_NODE_PREFIX="$(nvm_node_prefix)"

  case "$1" in
    "stable" | "unstable" | "${NVM_IOJS_PREFIX}" | "${NVM_NODE_PREFIX}")
      return
    ;;
    *)
      nvm_err "Only implicit aliases 'stable', 'unstable', '${NVM_IOJS_PREFIX}', and '${NVM_NODE_PREFIX}' are supported."
      return 1
    ;;
  esac
}

nvm_process_parameters() {
  local NVM_AUTO_MODE
  NVM_AUTO_MODE='use'
  while [ "$#" -ne 0 ]; do
    case "$1" in
      --install) NVM_AUTO_MODE='install' ;;
      --no-use) NVM_AUTO_MODE='none' ;;
    esac
    shift
  done
  nvm_auto "${NVM_AUTO_MODE}"
}

nvm() {
  # `nvm __nvmimic <function> [args]` runs one of nvm's functions in the
  # nvmimic binary. Its output goes straight to the terminal. What it changes
